from __future__ import annotations

from dataclasses import dataclass
from typing import Any, Dict, Optional

import torch


def _deep_get(d: Dict[str, Any], key: str, default: Any) -> Any:
    cur: Any = d
    for p in str(key).split("."):
        if not isinstance(cur, dict) or p not in cur:
            return default
        cur = cur[p]
    return cur


def _deep_merge(base: Dict[str, Any], upd: Dict[str, Any]) -> Dict[str, Any]:
    out = dict(base)
    for k, v in (upd or {}).items():
        if isinstance(v, dict) and isinstance(out.get(k), dict):
            out[k] = _deep_merge(out[k], v)
        else:
            out[k] = v
    return out


@dataclass
class PluginManager:
    """
    Lightweight plugin config manager.
    This is intentionally minimal: it owns config defaults + dependency checks + state_dict scaffolding.
    """

    cfg: Dict[str, Any]
    num_classes: int
    device: torch.device

    @staticmethod
    def default_cfg() -> Dict[str, Any]:
        return {
            "pseudo_conf_mask": {
                "enabled": False,
                "threshold": 0.85,
                "min_valid_ratio": 0.01,
                "min_valid_pixels": 0,
                "ignore_index": 255,
                "fallback": "skip",  # skip|original|zero
            },
            "depth_boundary_prior": {
                "enabled": False,
                # Uses offline depth priors generated by tools/generate_wildpass_depth_prior.py
                # Expect structure: <depth_prior_root>/depth_boundary_npy/<relative_path>.npy (0/1 uint8).
                "depth_prior_root": "",
                # Downweight semantic boundary pixels when depth boundary does NOT support them.
                "weight_on_inconsistent": 0.2,
                # Dilate semantic boundary before comparing (in pixels, via maxpool radius).
                "semantic_boundary_dilate": 1,
                # If depth boundary is missing for a sample, fallback behavior:
                #   skip: do nothing; ones: use all-one weights; error: raise.
                "missing_fallback": "skip",  # skip|ones|error
            },
            "depth_confidence": {
                "enabled": False,
                "edge_consistency": True,
                "smooth_region_consistency": True,
                "weight_min": 0.3,
                "weight_max": 1.0,
                "edge_beta": 0.5,
                "smooth_beta": 0.5,
                "ignore_index": 255,
                "debug_vis": False,
            },
            "efficient_tam_memory": {
                "enabled": False,
                "mode": "pool",
                "compress_ratio": 0.5,
                "pool_stride": 2,
                "apply_in_pl": True,
                "apply_in_train": True,
            },
            "efficient_sam2_sparse": {
                "enabled": False,
                "mode": "attn_topk",
                "keep_ratio": 0.5,
                "min_keep_tokens": 64,
                "saliency_source": "feature_norm",
                "cache_saliency": True,
                "fallback_full_when_uncertain": True,
                "apply_in_pl": True,
                "apply_in_train": True,
                "boundary_reserve_ratio": 0.125,
            },
            "pano_smb": {
                "enabled": False,
                "min_tokens": 256,
                "verbose": False,
                "log_interval": 200,
            },
            "geo_memory": {
                "enabled": False,
                "mode": "diagnosis",
                "log_jsonl": "experiments/geo_memory/results/geo_memory_diag.jsonl",
                "erp_width": 4096,
                "erp_height": 1024,
                "window_size": 1024,
                "stride": 384,
                "allow_tensor_order_inference": False,
                "seam_selection_enabled": False,
                "latitude_source": "mem_hw_token_row",
                "token_writer": {
                    "enabled": False,
                    "summary_jsonl": "experiments/geo_memory/results/token_geometry_summary.jsonl",
                    "token_jsonl": "experiments/geo_memory/results/token_geometry_diag.jsonl",
                    "max_records": 5,
                    "max_summary_records": 200,
                    "sample_rate": 1.0,
                    "first_n_batches": 1,
                },
            },
        }

    @classmethod
    def from_args(cls, args, num_classes: int, device: torch.device) -> "PluginManager":
        user_cfg = getattr(args, "plugins_cfg", None)
        if not isinstance(user_cfg, dict):
            user_cfg = {}
        cfg = _deep_merge(cls.default_cfg(), user_cfg)
        pm = cls(cfg=cfg, num_classes=int(num_classes), device=device)
        return pm

    def enabled(self, name: str) -> bool:
        return bool(_deep_get(self.cfg, f"{name}.enabled", False))

    def format_enabled_plugins(self, prefix: str = "") -> str:
        enabled = [k for k, v in self.cfg.items() if isinstance(v, dict) and bool(v.get("enabled", False))]
        if not enabled:
            return f"{prefix}enabled=[] (base behavior)"
        return f"{prefix}enabled={sorted(enabled)}"

    # ---- state hooks (to be filled by specific plugins) ----
    def state_dict(self) -> Dict[str, Any]:
        return {}

    def load_state_dict(self, state: Dict[str, Any]) -> None:
        _ = state

